export const MOMO_V2_FRAMES: Record<MomoV2Action, MomoPathDef[][]> = {
  ...BASE_MOMO_FRAMES,
  eat: BASE_MOMO_FRAMES.idle.map((frame, index) => {
    const bite = Math.floor(index / 2) % 2;
    return [
      ...frame,
      // Tangan memegang rumpun rumput di depan mulut.
      { d: 'M20 40H28V44H20ZM36 40H44V44H36Z', fill: '#71BA83' },
      { d: bite ? 'M28 40H36V42H28Z' : 'M28 40H36V44H28Z', fill: '#15221A' },
      { d: bite
        ? 'M30 38H32V44H30ZM34 40H36V46H34Z'
        : 'M28 34H30V42H28ZM32 36H34V44H32ZM36 34H38V42H36Z', fill: '#355E3B' },
    ];
  }),
};

// Cache canvas offscreen untuk render 60 FPS tanpa beban CPU
const canvasCache = new Map<string, HTMLCanvasElement>();
let seasonCanvas: HTMLCanvasElement | null = null;

export function getMomoV2Canvas(action: MomoV2Action, frameIndex: number): HTMLCanvasElement | null {
  if (typeof document === 'undefined') return null;
  const frames = MOMO_V2_FRAMES[action];
  if (!frames || frames.length === 0) return null;
  const safeIdx = Math.abs(frameIndex) % frames.length;
  const cacheKey = `${action}_${safeIdx}`;
  const existing = canvasCache.get(cacheKey);
  if (existing) return existing;

  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.imageSmoothingEnabled = false;
  const pathDefs = frames[safeIdx] || [];
  for (const def of pathDefs) {
    ctx.fillStyle = def.fill;
    const path2d = new Path2D(def.d);
    ctx.fill(path2d);
  }

  canvasCache.set(cacheKey, canvas);
  return canvas;
}

/**
 * Menggambar Momo v2 stepped animation di koordinat tertentu pada kanvas target
 */
export function drawMomoV2(
  ctx: CanvasRenderingContext2D,
  action: MomoV2Action,
  frameIndex: number,
  destX: number,
  destY: number,
  scale: number = 1,
  flipX: boolean = false,
  season?: IslandSeason,
  seasonOptions?: MomoSeasonRenderOptions
): void {
  const frameCanvas = getMomoV2Canvas(action, frameIndex);
  if (!frameCanvas) return;

  let sprite = frameCanvas;
  if (season) {
    // Rasterkan aksesori pada grid yang sama dengan tubuh sebelum pengecilan pixel art.
    if (!seasonCanvas) {
      seasonCanvas = document.createElement('canvas');
      seasonCanvas.width = 64;
      seasonCanvas.height = 64;
    }
    const layer = seasonCanvas.getContext('2d');
    if (layer) {
      layer.imageSmoothingEnabled = false;
      layer.clearRect(0, 0, 64, 64);
      layer.drawImage(frameCanvas, 0, 0);
      drawMomoSeasonLayer(layer, action, frameIndex, season, seasonOptions);
      sprite = seasonCanvas;
    }
  }

  ctx.save();
  ctx.imageSmoothingEnabled = false;
  const drawW = 64 * scale;
  const drawH = 64 * scale;

  if (flipX) {
    ctx.translate(destX + drawW, destY);
    ctx.scale(-1, 1);
    ctx.drawImage(sprite, 0, 0, drawW, drawH);
  } else {
    ctx.translate(destX, destY);
    ctx.drawImage(sprite, 0, 0, drawW, drawH);
  }
  ctx.restore();
}
